// analyzer/constraintSolver.ts:78
pub(crate) const MAX_SUBTYPE_COUNT_FOR_TYPE_VAR_LOWER_BOUND: u32 = 64;

// analyzer/constraintSolver.ts:82
pub(crate) const LOG_CONSTRAINTS_UPDATES: bool = false;

// analyzer/constraintSolver.ts:90
/// TS defaults: flags = AssignTypeFlags.Default, recursionCount = 0.
pub fn assign_type_var(
    evaluator: &TypeEvaluator,
    dest_type: TypeVarType,
    src_type: P<Type>,
    diag: Option<P<DiagnosticAddendum>>,
    constraints: Option<P<ConstraintTracker>>,
    flags: AssignTypeFlags,
    recursion_count: u32,
) -> bool {
    let mut dest_type = dest_type;
    let mut src_type = src_type;
    let is_assignable: bool;

    if LOG_CONSTRAINTS_UPDATES {
        let indent = " ".repeat(recursion_count as usize * 2);
        println!("{indent}");
        println!("{indent}assignTypeVar called with");
        println!(
            "{indent}destType: {}",
            evaluator.print_type(dest_type.0, None)
        );
        println!("{indent}srcType: {}", evaluator.print_type(src_type, None));
        println!("{indent}flags: {}", flags.0);
        if let Some(constraints) = constraints {
            log_constraints(evaluator, constraints, &indent);
        }
    }

    // If both src and dest types are packed, unpack them both.
    if is_unpacked(dest_type.0) && is_unpacked(src_type) {
        dest_type = TypeVarType::clone_for_packed(dest_type);
        src_type = make_packed(src_type);
    }

    // If the TypeVar doesn't have a scope ID, then it's being used
    // outside of a valid TypeVar scope. This will be reported as a
    // separate error. Just ignore this case to avoid redundant errors.
    if dest_type
        .d()
        .priv_
        .borrow()
        .scope_id
        .as_deref()
        .is_none_or(str::is_empty)
    {
        return true;
    }

    if TypeVarType::is_bound(dest_type) && !TypeVarType::is_unification(dest_type).unwrap_or(false)
    {
        return assign_bound_type_var(evaluator, dest_type, src_type, diag, flags);
    }

    // Handle type[T] as a dest and a special form as a source.
    if TypeBase::is_instantiable(dest_type.0)
        && is_instantiable_class(src_type)
        && evaluator.is_special_form_class(ClassType(src_type), flags)
    {
        return false;
    }

    // An TypeVar can always be assigned to itself, but we won't record this in the constraints.
    if is_type_same(dest_type.0, src_type, &TypeSameOptions::default(), 0) {
        return true;
    }

    if is_param_spec(dest_type.0) {
        // Handle ParamSpecs specially.
        is_assignable = assign_param_spec(
            evaluator,
            ParamSpecType(dest_type.0),
            src_type,
            diag,
            constraints,
            recursion_count,
        );
    } else {
        let (dest_is_in_union, dest_is_unpacked) = {
            let priv_ = dest_type.d().priv_.borrow();
            (
                priv_.is_in_union.unwrap_or(false),
                priv_.is_unpacked.unwrap_or(false),
            )
        };
        if is_type_var_tuple(dest_type.0) && !dest_is_in_union {
            if dest_is_unpacked {
                let tuple_class_type = evaluator.get_tuple_class_type();

                if !is_unpacked(src_type) {
                    if let Some(tuple_class_type) = tuple_class_type {
                        // Package up the type into a tuple.
                        src_type = convert_to_instance(
                            specialize_tuple_class(
                                tuple_class_type,
                                &[TupleTypeArg {
                                    type_: src_type,
                                    is_unbounded: false,
                                    is_optional: None,
                                }],
                                /* isTypeArgExplicit */ true,
                                /* isUnpacked */ true,
                            )
                            .0,
                            true,
                        );
                    }
                }
            } else {
                src_type = make_unpacked(src_type);
            }
        }

        // If we're assigning an unpacked TypeVarTuple to a regular TypeVar,
        // we need to treat it as a union of the unpacked TypeVarTuple.
        if is_type_var_tuple(src_type) {
            let (src_is_unpacked, src_is_in_union) = {
                let priv_ = TypeVarType(src_type).d().priv_.borrow();
                (
                    priv_.is_unpacked.unwrap_or(false),
                    priv_.is_in_union.unwrap_or(false),
                )
            };
            if src_is_unpacked && !src_is_in_union && !is_type_var_tuple(dest_type.0) {
                src_type = TypeVarType::clone_for_unpacked(
                    TypeVarType(src_type),
                    /* isInUnion */ true,
                )
                .0;
            }
        }

        // Handle the constrained case. This case needs to be handled specially
        // because type narrowing isn't used in this case. For example, if the
        // source type is "Literal[1]" and the constraint list includes the type
        // "float", the resulting type is float.
        if TypeVarType::has_constraints(dest_type) {
            is_assignable = assign_constrained_type_var(
                evaluator,
                dest_type,
                src_type,
                diag,
                constraints,
                flags,
                recursion_count,
            );
        } else {
            is_assignable = assign_unconstrained_type_var(
                evaluator,
                dest_type,
                src_type,
                diag,
                constraints,
                flags,
                recursion_count,
            );
        }
    }

    if LOG_CONSTRAINTS_UPDATES {
        let indent = " ".repeat(recursion_count as usize * 2);
        println!("{indent}");
        if let Some(constraints) = constraints {
            log_constraints(evaluator, constraints, &indent);
        }
    }

    is_assignable
}

// analyzer/constraintSolver.ts:218
pub fn solve_constraints(
    evaluator: &TypeEvaluator,
    constraints: P<ConstraintTracker>,
    options: Option<&SolveConstraintsOptions>,
) -> ConstraintSolution {
    let mut solution_sets: Vec<P<ConstraintSolutionSet>> = Vec::new();

    constraints.do_for_each_constraint_set(&mut |constraint_set, _| {
        let solution_set = solve_constraint_set(evaluator, constraint_set, options);
        solution_sets.push(solution_set);
    });

    ConstraintSolution::new(Some(&solution_sets))
}

// analyzer/constraintSolver.ts:234
pub fn apply_source_solution_to_constraints(
    constraints: P<ConstraintTracker>,
    src_solution: &ConstraintSolution,
) {
    if src_solution.is_empty() {
        return;
    }

    constraints.do_for_each_constraint_set(&mut |constraint_set, _| {
        for entry in constraint_set.get_type_vars() {
            constraint_set.set_bounds(
                entry.type_var,
                entry.lower_bound.map(|lower_bound| {
                    apply_solved_type_vars(
                        lower_bound,
                        src_solution,
                        &ApplyTypeVarOptions::default(),
                    )
                }),
                entry.upper_bound.map(|upper_bound| {
                    apply_solved_type_vars(
                        upper_bound,
                        src_solution,
                        &ApplyTypeVarOptions::default(),
                    )
                }),
                entry.retain_literals,
            );
        }
    });
}

// analyzer/constraintSolver.ts:251
pub fn solve_constraint_set(
    evaluator: &TypeEvaluator,
    constraint_set: P<ConstraintSet>,
    options: Option<&SolveConstraintsOptions>,
) -> P<ConstraintSolutionSet> {
    let solution_set = ConstraintSolutionSet::new();

    // Solve the type variables.
    constraint_set.do_for_each_type_var(&mut |entry| {
        solve_type_var_recursive(evaluator, constraint_set, options, solution_set, entry);
    });

    solution_set
}

// analyzer/constraintSolver.ts:266
pub(crate) fn solve_type_var_recursive(
    evaluator: &TypeEvaluator,
    constraint_set: P<ConstraintSet>,
    options: Option<&SolveConstraintsOptions>,
    solution_set: P<ConstraintSolutionSet>,
    entry: &TypeVarConstraints,
) -> Option<P<Type>> {
    // If this TypeVar already has a solution, don't attempt to re-solve it.
    if solution_set.has_type(entry.type_var) {
        return solution_set.get_type(entry.type_var);
    }

    // Protect against infinite recursion by setting the initial value to undefined.
    solution_set.set_type(entry.type_var, None);
    let mut value = get_type_var_type(
        evaluator,
        constraint_set,
        entry.type_var,
        options.and_then(|options| options.use_lower_bound_only),
    );

    if let Some(current_value) = value {
        // Are there any unsolved TypeVars in this type?
        let type_vars = get_type_var_args_recursive(current_value, 0);

        if !type_vars.is_empty() {
            let dependent_solution = ConstraintSolution::new(None);

            for type_var in type_vars {
                // Don't attempt to replace a TypeVar with itself.
                if is_type_same(
                    type_var.0,
                    entry.type_var.0,
                    &TypeSameOptions {
                        ignore_type_flags: Some(true),
                        ..Default::default()
                    },
                    0,
                ) {
                    continue;
                }

                // Don't attempt to solve or replace bound TypeVars.
                if TypeVarType::is_bound(type_var) {
                    continue;
                }

                let Some(dependent_entry) = constraint_set.get_type_var(type_var) else {
                    continue;
                };

                let dependent_type = solve_type_var_recursive(
                    evaluator,
                    constraint_set,
                    options,
                    solution_set,
                    &dependent_entry,
                );

                if let Some(dependent_type) = dependent_type {
                    dependent_solution.set_type(type_var, dependent_type);
                }
            }

            // Apply the dependent TypeVar values to the current TypeVar value.
            if !dependent_solution.is_empty() {
                value = Some(apply_solved_type_vars(
                    current_value,
                    &dependent_solution,
                    &ApplyTypeVarOptions::default(),
                ));
            }
        }
    }

    solution_set.set_type(entry.type_var, value);
    value
}

// analyzer/constraintSolver.ts:335
/// TS defaults: usageOffset = undefined.
pub fn add_constraints_for_expected_type(
    evaluator: &TypeEvaluator,
    type_: ClassType,
    expected_type: P<Type>,
    constraints: P<ConstraintTracker>,
    live_type_var_scopes: Option<&[TypeVarScopeId]>,
    usage_offset: Option<i32>,
) -> bool {
    if is_any(expected_type) {
        let type_params = type_.d().shared.get().type_params.borrow().clone();
        for type_param in type_params.iter().copied() {
            constraints.set_bounds(type_param, Some(expected_type), Some(expected_type), None);
        }
        return true;
    }

    let mut expected_type = expected_type;
    if is_type_var(expected_type) && TypeVarType::is_self(TypeVarType(expected_type)) {
        if let Some(bound_type) = TypeVarType(expected_type).d().shared.get().bound_type.get() {
            expected_type = bound_type;
        }
    }

    if !is_class(expected_type) {
        return false;
    }
    let expected_class = ClassType(expected_type);

    // If the expected type is generic (but not specialized), we can't proceed.
    let expected_type_args = expected_class.d().priv_.borrow().type_args.clone();
    let Some(expected_type_args) = expected_type_args else {
        return evaluator.assign_type(
            type_.0,
            expected_type,
            /* diag */ None,
            Some(constraints),
            AssignTypeFlags::PopulateExpectedType,
            0,
        );
    };

    evaluator.infer_variance_for_class(type_);

    // If the expected type is the same as the target type (commonly the case),
    // we can use a faster method.
    if ClassType::is_same_generic_class(expected_class, type_, 0) {
        let solution = build_solution_from_specialized_class(expected_class);
        let type_params = ClassType::get_type_params(expected_class);
        for type_param in type_params.iter().copied() {
            let mut type_arg_value = solution.get_main_solution_set().get_type(type_param);

            if let (Some(value), Some(live_type_var_scopes)) =
                (type_arg_value, live_type_var_scopes)
            {
                type_arg_value = Some(transform_expected_type(
                    value,
                    live_type_var_scopes,
                    usage_offset,
                ));
            }

            if let Some(type_arg_value) = type_arg_value {
                let variance = TypeVarType::get_variance(type_param);

                constraints.set_bounds(
                    type_param,
                    if variance == Variance::Covariant {
                        None
                    } else {
                        Some(type_arg_value)
                    },
                    if variance == Variance::Contravariant {
                        None
                    } else {
                        Some(type_arg_value)
                    },
                    None,
                );
            }
        }
        return true;
    }

    // Create a generic version of the expected type.
    let expected_type_scope_id = get_type_var_scope_id(expected_type);
    let synth_expected_type_args: Vec<TypeVarType> = ClassType::get_type_params(expected_class)
        .iter()
        .enumerate()
        .map(|(index, type_param)| {
            let type_var = TypeVarType::create_instance(
                &format!("__dest{index}"),
                if is_param_spec(type_param.0) {
                    TypeVarKind::ParamSpec
                } else {
                    TypeVarKind::TypeVar
                },
            );
            type_var.d().shared.get().is_synthesized.set(true);

            // Use invariance here so we set the lower and upper bound on the TypeVar.
            type_var
                .d()
                .shared
                .get()
                .declared_variance
                .set(Variance::Invariant);
            type_var.d().priv_.borrow_mut().scope_id = expected_type_scope_id;
            type_var
        })
        .collect();
    let synth_expected_type_arg_types: Vec<P<Type>> =
        synth_expected_type_args.iter().map(|t| t.0).collect();
    let generic_expected_type = ClassType::specialize(
        expected_class,
        Some(&synth_expected_type_arg_types),
        None,
        false,
        None,
        None,
    );

    // For each type param in the target type, create a placeholder type variable.
    let type_args: Vec<P<Type>> = ClassType::get_type_params(type_)
        .iter()
        .enumerate()
        .map(|(index, type_param)| {
            let type_var = TypeVarType::create_instance(
                &format!("__source{index}"),
                if is_param_spec(type_param.0) {
                    TypeVarKind::ParamSpec
                } else {
                    TypeVarKind::TypeVar
                },
            );
            let shared = type_var.d().shared.get();
            shared.is_synthesized.set(true);
            shared.synthesized_index.set(Some(index as i32));
            shared.is_exempt_from_bound_check.set(true);
            TypeVarType::clone_as_unification_var(type_var, None).0
        })
        .collect();

    let specialized_type = ClassType::specialize(type_, Some(&type_args), None, false, None, None);
    let synthetic_constraints = ConstraintTracker::new();
    if evaluator.assign_type(
        generic_expected_type.0,
        specialized_type.0,
        /* diag */ None,
        Some(synthetic_constraints),
        AssignTypeFlags::PopulateExpectedType,
        0,
    ) {
        let mut is_result_valid = true;

        for (index, &type_var) in synth_expected_type_args.iter().enumerate() {
            let mut synth_type_var = get_type_var_type(
                evaluator,
                synthetic_constraints.get_main_constraint_set(),
                type_var,
                None,
            );
            let mut other_subtypes: Vec<P<Type>> = Vec::new();

            // If the resulting type is a union, try to find a matching type var and move
            // the remaining subtypes to the "otherSubtypes" array.
            if let Some(synth) = synth_type_var {
                if is_param_spec(type_var.0) && is_function(synth) {
                    synth_type_var = Some(simplify_function_to_param_spec(FunctionType(synth)));
                }
            }
            if let Some(synth) = synth_type_var {
                if is_union(synth) {
                    let mut found_synth_type_var: Option<TypeVarType> = None;

                    let subtypes = UnionType(synth).d().priv_.borrow().subtypes.clone();
                    for subtype in sort_types(&subtypes) {
                        let is_synth_index_type_var = is_type_var(subtype) && {
                            let shared = TypeVarType(subtype).d().shared.get();
                            shared.is_synthesized.get() && shared.synthesized_index.get().is_some()
                        };
                        if is_synth_index_type_var && found_synth_type_var.is_none() {
                            found_synth_type_var = Some(TypeVarType(subtype));
                        } else {
                            other_subtypes.push(subtype);
                        }
                    }

                    if let Some(found_synth_type_var) = found_synth_type_var {
                        synth_type_var = Some(found_synth_type_var.0);
                    }
                }
            }

            // Is this one of the synthesized type vars we allocated above? If so,
            // the type arg that corresponds to this type var maps back to the target type.
            let synthesized_index =
                synth_type_var
                    .filter(|&synth| is_type_var(synth))
                    .and_then(|synth| {
                        let shared = TypeVarType(synth).d().shared.get();
                        if shared.is_synthesized.get() {
                            shared.synthesized_index.get()
                        } else {
                            None
                        }
                    });
            if let Some(synthesized_index) = synthesized_index {
                let target_type_var =
                    ClassType::get_type_params(specialized_type)[synthesized_index as usize];
                if index < expected_type_args.len() {
                    let mut type_arg_value: Option<P<Type>> =
                        transform_possible_recursive_type_alias(Some(expected_type_args[index]), 0);

                    if !other_subtypes.is_empty() {
                        let mut subtypes: Vec<P<Type>> = Vec::new();
                        subtypes.extend(type_arg_value);
                        subtypes.extend(other_subtypes.iter().copied());
                        type_arg_value = Some(combine_types(&subtypes, None));
                    }

                    if let Some(live_type_var_scopes) = live_type_var_scopes {
                        type_arg_value = type_arg_value.map(|value| {
                            transform_expected_type(value, live_type_var_scopes, usage_offset)
                        });
                    }

                    match type_arg_value {
                        Some(type_arg_value)
                            if assign_type_var(
                                evaluator,
                                target_type_var,
                                type_arg_value,
                                /* diag */ None,
                                Some(constraints),
                                AssignTypeFlags::RetainLiteralsForTypeVar,
                                0,
                            ) => {}
                        _ => {
                            is_result_valid = false;
                        }
                    }
                }
            }
        }

        return is_result_valid;
    }

    false
}

// analyzer/constraintSolver.ts:514
pub(crate) fn strip_literals_for_lower_bound(
    evaluator: &TypeEvaluator,
    type_var: TypeVarType,
    lower_bound: P<Type>,
) -> P<Type> {
    if is_type_var_tuple(type_var.0) {
        strip_literal_value_for_unpacked_tuple(evaluator, lower_bound)
    } else {
        strip_type_form(evaluator.strip_literal_value(lower_bound))
    }
}

// analyzer/constraintSolver.ts:520
pub(crate) fn get_type_var_type(
    evaluator: &TypeEvaluator,
    constraint_set: P<ConstraintSet>,
    type_var: TypeVarType,
    use_lower_bound_only: Option<bool>,
) -> Option<P<Type>> {
    let entry = constraint_set.get_type_var(type_var)?;

    if is_param_spec(type_var.0) {
        let lower_bound = entry.lower_bound?;

        if is_function(lower_bound) {
            return Some(lower_bound);
        }

        if is_any_or_unknown(lower_bound) {
            return Some(ParamSpecType::get_unknown().0);
        }
    }

    let mut result: Option<P<Type>> = None;

    let mut lower_bound = entry.lower_bound;
    if let Some(current_lower_bound) = lower_bound {
        if !entry.retain_literals.unwrap_or(false) {
            let lower_no_literals =
                strip_literals_for_lower_bound(evaluator, type_var, current_lower_bound);

            // If we can widen the lower bound to a non-literal type without
            // exceeding the upper bound, use the widened type.
            if lower_no_literals != current_lower_bound {
                let within_upper_bound = match entry.upper_bound {
                    None => true,
                    Some(upper_bound) => evaluator.assign_type(
                        upper_bound,
                        lower_no_literals,
                        None,
                        None,
                        AssignTypeFlags::Default,
                        0,
                    ),
                };
                if within_upper_bound {
                    if TypeVarType::has_constraints(type_var) {
                        // Does it still match a value constraint?
                        let constraints = type_var.d().shared.get().constraints.borrow().clone();
                        if constraints.iter().any(|&constraint| {
                            is_type_same(
                                lower_no_literals,
                                constraint,
                                &TypeSameOptions::default(),
                                0,
                            )
                        }) {
                            lower_bound = Some(lower_no_literals);
                        }
                    } else {
                        lower_bound = Some(lower_no_literals);
                    }
                }
            }
        }

        result = lower_bound;
    } else if !use_lower_bound_only.unwrap_or(false) {
        result = entry.upper_bound;
    }

    result
}

// analyzer/constraintSolver.ts:579
pub(crate) fn assign_bound_type_var(
    evaluator: &TypeEvaluator,
    dest_type: TypeVarType,
    src_type: P<Type>,
    diag: Option<P<DiagnosticAddendum>>,
    flags: AssignTypeFlags,
) -> bool {
    // Handle Any as a source.
    if is_any_or_unknown(src_type)
        || (is_class(src_type) && ClassType::derives_from_any_or_unknown(ClassType(src_type)))
    {
        return true;
    }

    // Is this the equivalent of an "Unknown" for a ParamSpec?
    if is_param_spec(dest_type.0)
        && is_function(src_type)
        && FunctionType::is_gradual_callable_form(FunctionType(src_type))
    {
        return true;
    }

    // Never is always assignable except in an invariant context.
    let is_invariant = flags.any(AssignTypeFlags::Invariant);
    if is_never(src_type) && !is_invariant {
        return true;
    }

    // Handle a type[Any] as a source.
    if is_class_instance(src_type)
        && ClassType::is_built_in(ClassType(src_type), Some(&[jsrt::atom!("type")]))
    {
        let type_args = ClassType(src_type).d().priv_.borrow().type_args.clone();
        let is_type_any = match &type_args {
            None => true,
            Some(type_args) => type_args.is_empty() || is_any_or_unknown(type_args[0]),
        };
        if is_type_any && TypeBase::is_instantiable(dest_type.0) {
            return true;
        }
    }

    // Emit an error unless this is a synthesized type variable used
    // for pseudo-generic classes.
    if !dest_type.d().shared.get().is_synthesized.get() || TypeVarType::is_self(dest_type) {
        if let Some(diag) = diag {
            let types = evaluator.print_src_dest_types(src_type, dest_type.0, None);
            diag.add_message(LocAddendum::type_assignment_mismatch().format(&[
                ("sourceType", &types.source_type),
                ("destType", &types.dest_type),
            ]));
        }
    }

    false
}

// analyzer/constraintSolver.ts:622
pub(crate) fn assign_unconstrained_type_var(
    evaluator: &TypeEvaluator,
    dest_type: TypeVarType,
    src_type: P<Type>,
    diag: Option<P<DiagnosticAddendum>>,
    constraints: Option<P<ConstraintTracker>>,
    flags: AssignTypeFlags,
    recursion_count: u32,
) -> bool {
    // `LocAddendum.typeAssignmentMismatch().format(evaluator.printSrcDestTypes(..))`.
    fn type_assignment_mismatch(types: CreateTypeEvaluatorPrintSrcDestTypesReturn) -> String {
        LocAddendum::type_assignment_mismatch().format(&[
            ("sourceType", &types.source_type),
            ("destType", &types.dest_type),
        ])
    }

    let is_invariant = flags.any(AssignTypeFlags::Invariant);
    let is_contravariant = flags.any(AssignTypeFlags::Contravariant) && !is_invariant;

    // Handle the unconstrained (but possibly bound) case.
    let cur_entry = constraints.and_then(|constraints| {
        constraints
            .get_main_constraint_set()
            .get_type_var(dest_type)
    });

    let mut cur_upper_bound = cur_entry.as_ref().and_then(|entry| entry.upper_bound);
    if cur_upper_bound.is_none() && !TypeVarType::is_self(dest_type) {
        cur_upper_bound = dest_type.d().shared.get().bound_type.get();
    }
    let cur_lower_bound = cur_entry.as_ref().and_then(|entry| entry.lower_bound);
    let mut new_lower_bound = cur_lower_bound;
    let mut new_upper_bound = cur_upper_bound;
    let diag_addendum = diag.map(|_| DiagnosticAddendum::new());

    let mut adj_src_type = src_type;

    // If the source is a class that is missing type arguments, fill
    // in missing type arguments with Unknown.
    if !flags.any(AssignTypeFlags::AllowUnspecifiedTypeArgs)
        && is_class(adj_src_type)
        && ClassType(adj_src_type)
            .d()
            .priv_
            .borrow()
            .include_subclasses
            .unwrap_or(false)
    {
        adj_src_type = specialize_with_default_type_args(ClassType(adj_src_type)).0;
    }

    if TypeBase::is_instantiable(dest_type.0) {
        if is_effectively_instantiable(adj_src_type, None, 0) {
            adj_src_type = convert_to_instance(adj_src_type, /* includeSubclasses */ false);
        } else {
            // Handle the case of a TypeVar that has a bound of `type`.
            let concrete_adj_src_type =
                evaluator.make_top_level_type_vars_concrete(adj_src_type, false, None);

            if is_effectively_instantiable(concrete_adj_src_type, None, 0) {
                adj_src_type = convert_to_instance(concrete_adj_src_type, true);
            } else {
                if let Some(diag) = diag {
                    diag.add_message(type_assignment_mismatch(evaluator.print_src_dest_types(
                        src_type,
                        dest_type.0,
                        None,
                    )));
                }
                return false;
            }
        }
    } else if is_type_var(src_type)
        && TypeBase::is_instantiable(src_type)
        && is_type_same(
            convert_to_instance(src_type, true),
            dest_type.0,
            &TypeSameOptions::default(),
            0,
        )
    {
        if let Some(diag) = diag {
            diag.add_message(type_assignment_mismatch(evaluator.print_src_dest_types(
                adj_src_type,
                dest_type.0,
                None,
            )));
        }
        return false;
    }

    if flags.any(AssignTypeFlags::PopulateExpectedType) {
        if flags.any(AssignTypeFlags::SkipPopulateUnknownExpectedType) && is_unknown(adj_src_type) {
            return true;
        }

        // If we're populating the expected type, constrain either the
        // lower type bound, upper type bound or both. Don't overwrite
        // an existing entry.
        if cur_entry.is_none() {
            if is_invariant {
                new_lower_bound = Some(adj_src_type);
                new_upper_bound = Some(adj_src_type);
            } else if is_contravariant {
                new_lower_bound = Some(adj_src_type);
            } else {
                new_upper_bound = Some(adj_src_type);
            }
        }
    } else if is_contravariant {
        // Update the upper bound.
        match cur_upper_bound {
            Some(cur_upper)
                if !is_type_same(dest_type.0, cur_upper, &TypeSameOptions::default(), 0) =>
            {
                if !is_type_same(
                    cur_upper,
                    adj_src_type,
                    &TypeSameOptions::default(),
                    recursion_count,
                ) {
                    if evaluator.assign_type(
                        cur_upper,
                        evaluator.make_top_level_type_vars_concrete(adj_src_type, false, None),
                        diag_addendum,
                        /* constraints */ None,
                        AssignTypeFlags::Default,
                        recursion_count,
                    ) {
                        // The srcType is narrower than the current upper bound, so replace it.
                        new_upper_bound = Some(adj_src_type);
                    } else if !evaluator.assign_type(
                        adj_src_type,
                        cur_upper,
                        diag_addendum,
                        /* constraints */ None,
                        AssignTypeFlags::Default,
                        recursion_count,
                    ) {
                        if let (Some(diag), Some(diag_addendum)) = (diag, diag_addendum) {
                            diag.add_message(type_assignment_mismatch(
                                evaluator.print_src_dest_types(cur_upper, adj_src_type, None),
                            ));
                            diag.add_addendum(diag_addendum);
                        }
                        return false;
                    }
                }
            }
            _ => {
                new_upper_bound = Some(adj_src_type);
            }
        }

        // Make sure we haven't narrowed it beyond the current lower bound.
        if let Some(cur_lower) = cur_lower_bound {
            let new_upper = new_upper_bound.unwrap();
            if !evaluator.assign_type(
                new_upper,
                cur_lower,
                /* diag */ None,
                /* constraints */ None,
                AssignTypeFlags::Default,
                recursion_count,
            ) {
                if let (Some(diag), Some(diag_addendum)) = (diag, diag_addendum) {
                    diag.add_message(type_assignment_mismatch(
                        evaluator.print_src_dest_types(cur_lower, new_upper, None),
                    ));
                    diag.add_addendum(diag_addendum);
                }
                return false;
            }
        }
    } else {
        match cur_lower_bound {
            Some(cur_lower)
                if !is_type_same(dest_type.0, cur_lower, &TypeSameOptions::default(), 0) =>
            {
                if is_type_same(
                    cur_lower,
                    adj_src_type,
                    &TypeSameOptions::default(),
                    recursion_count,
                ) {
                    // If this is an invariant context and there is currently no upper bound
                    // established, use the "no literals" version of the lower bound rather
                    // than a version that has literals.
                    if new_upper_bound.is_none()
                        && is_invariant
                        && cur_entry
                            .as_ref()
                            .is_some_and(|entry| !entry.retain_literals.unwrap_or(false))
                    {
                        new_lower_bound = Some(strip_literals_for_lower_bound(
                            evaluator, dest_type, cur_lower,
                        ));
                    }
                } else if evaluator.assign_type(
                    cur_lower,
                    adj_src_type,
                    diag_addendum,
                    constraints,
                    flags,
                    recursion_count,
                ) {
                    // No need to widen. Stick with the existing type unless it's unknown
                    // or partly unknown, in which case we'll replace it with a known type
                    // as long as it doesn't violate the current lower bound.
                    if is_partly_unknown(cur_lower, 0)
                        && !is_unknown(adj_src_type)
                        && evaluator.assign_type(
                            adj_src_type,
                            cur_lower,
                            /* diag */ None,
                            constraints,
                            AssignTypeFlags::Default,
                            recursion_count,
                        )
                    {
                        new_lower_bound = Some(adj_src_type);
                    } else {
                        new_lower_bound = Some(cur_lower);

                        if let Some(constraints) = constraints {
                            new_lower_bound = Some(evaluator.solve_and_apply_constraints(
                                cur_lower,
                                constraints,
                                None,
                                None,
                            ));
                        }
                    }
                } else if is_type_var(cur_lower)
                    && !is_type_var(adj_src_type)
                    && evaluator.assign_type(
                        evaluator.make_top_level_type_vars_concrete(cur_lower, false, None),
                        adj_src_type,
                        diag_addendum,
                        constraints,
                        flags,
                        recursion_count,
                    )
                {
                    // If the existing lower bound was a TypeVar that is not
                    // part of the current context we can replace it with the new
                    // source type.
                    new_lower_bound = Some(adj_src_type);
                } else if evaluator.assign_type(
                    adj_src_type,
                    cur_lower,
                    /* diag */ None,
                    constraints,
                    AssignTypeFlags::Default,
                    recursion_count,
                ) {
                    // If the source is a TypeVar that just got assigned the value
                    // of the current lower bound, don't replace the current lower
                    // bound with the TypeVar.
                    if !is_type_var(adj_src_type) {
                        new_lower_bound = Some(adj_src_type);
                    }
                } else if is_type_var_tuple(dest_type.0) {
                    let widened_type = widen_type_for_type_var_tuple(
                        evaluator,
                        cur_lower,
                        adj_src_type,
                        is_invariant,
                        recursion_count,
                    );
                    let Some(widened_type) = widened_type else {
                        if let Some(diag) = diag {
                            diag.add_message(type_assignment_mismatch(
                                evaluator.print_src_dest_types(cur_lower, adj_src_type, None),
                            ));
                        }
                        return false;
                    };

                    new_lower_bound = Some(widened_type);
                } else {
                    let object_type = evaluator.get_object_type();

                    // If this is an invariant context and there is currently no upper bound
                    // established, use the "no literals" version of the lower bound rather
                    // than a version that has literals.
                    let mut cur_lower = cur_lower;
                    if new_upper_bound.is_none()
                        && is_invariant
                        && cur_entry
                            .as_ref()
                            .is_some_and(|entry| !entry.retain_literals.unwrap_or(false))
                    {
                        cur_lower = strip_literals_for_lower_bound(evaluator, dest_type, cur_lower);
                    }

                    let mut cur_solved_lower_bound = cur_lower;

                    if let Some(constraints) = constraints {
                        cur_solved_lower_bound = evaluator.solve_and_apply_constraints(
                            cur_lower,
                            constraints,
                            None,
                            None,
                        );
                    }

                    // In some extreme edge cases, the lower bound can become
                    // a union with so many subtypes that performance grinds to a
                    // halt. We'll detect this case and widen the resulting type
                    // to an 'object' instead of making the union even bigger. This
                    // is still a valid solution to the TypeVar.
                    let options = CombineTypesOptions {
                        max_subtype_count: Some(MAX_SUBTYPE_COUNT_FOR_TYPE_VAR_LOWER_BOUND),
                        ..Default::default()
                    };
                    if is_union(cur_solved_lower_bound)
                        && UnionType(cur_solved_lower_bound)
                            .d()
                            .priv_
                            .borrow()
                            .subtypes
                            .len()
                            > MAX_SUBTYPES_FOR_INFERRED_TYPE as usize
                        && TypeVarType::has_bound(dest_type)
                        && is_class_instance(object_type)
                    {
                        new_lower_bound = Some(combine_types(
                            &[cur_solved_lower_bound, object_type],
                            Some(&options),
                        ));
                    } else {
                        new_lower_bound = Some(combine_types(
                            &[cur_solved_lower_bound, adj_src_type],
                            Some(&options),
                        ));
                    }
                }
            }
            _ => {
                // There was previously no lower bound. We've now established one.
                // Apply an occurs check: if `adjSrcType` references `destType`
                // (the TypeVar being solved) at a strictly nested position
                // (e.g. `R := F[R]` or `R := R | Awaitable[R]`), recording it as
                // the lower bound creates a cyclic constraint that subsequent
                // widening / substitution rounds expand into an exponentially
                // growing recursive type. Such a constraint has no finite
                // solution, so report the assignment as a failure rather than
                // letting the analyzer hang. See microsoft/pyright#11413.
                //
                // Top-level union members that are exactly `destType` (e.g.
                // `T := T | int` arising from protocol matching against `T | int`)
                // are *not* considered cyclic - the original `adjSrcType` is
                // recorded as the lower bound and existing logic resolves it.
                if type_var_occurs_in(dest_type, adj_src_type) {
                    if let Some(diag) = diag {
                        diag.add_message(type_assignment_mismatch(evaluator.print_src_dest_types(
                            adj_src_type,
                            dest_type.0,
                            None,
                        )));
                    }
                    return false;
                }
                new_lower_bound = Some(adj_src_type);
            }
        }

        // If this is an invariant context, make sure the lower bound
        // isn't too wide.
        if is_invariant {
            if let Some(new_lower) = new_lower_bound {
                let child_diag = diag.map(|diag| diag.create_addendum());
                if !evaluator.assign_type(
                    adj_src_type,
                    new_lower,
                    child_diag,
                    /* constraints */ None,
                    AssignTypeFlags::Default,
                    recursion_count,
                ) {
                    if let (Some(diag), Some(_)) = (diag, diag_addendum) {
                        diag.add_message(type_assignment_mismatch(evaluator.print_src_dest_types(
                            new_lower,
                            adj_src_type,
                            None,
                        )));
                    }
                    return false;
                }
            }
        }

        // Make sure we don't exceed the upper bound.
        if let (Some(cur_upper), Some(new_lower)) = (cur_upper_bound, new_lower_bound) {
            if !is_type_same(
                cur_upper,
                new_lower,
                &TypeSameOptions::default(),
                recursion_count,
            ) {
                let child_diag = diag.map(|diag| diag.create_addendum());
                if !evaluator.assign_type(
                    cur_upper,
                    new_lower,
                    child_diag,
                    /* constraints */ None,
                    AssignTypeFlags::Default,
                    recursion_count,
                ) {
                    if let (Some(diag), Some(_)) = (diag, diag_addendum) {
                        diag.add_message(type_assignment_mismatch(
                            evaluator.print_src_dest_types(new_lower, cur_upper, None),
                        ));
                    }
                    return false;
                }
            }
        }
    }

    if new_upper_bound.is_none() && is_invariant {
        new_upper_bound = new_lower_bound;
    }

    // If there's a bound type, make sure the source is assignable to it.
    if let Some(bound_type) = dest_type.d().shared.get().bound_type.get() {
        let updated_type = new_lower_bound.or(new_upper_bound).unwrap();

        // If the dest is a Type[T] but the source is not a valid Type,
        // skip the assignType check and the diagnostic addendum, which will
        // be confusing and inaccurate.
        if TypeBase::is_instantiable(dest_type.0)
            && !is_effectively_instantiable(
                src_type,
                Some(&IsInstantiableOptions {
                    honor_type_var_bounds: Some(true),
                }),
                0,
            )
        {
            return false;
        }

        // In general, bound types cannot be generic, but the "Self" type is an
        // exception. In this case, we need to use the original constraints
        // to solve for the generic type variable(s) in the bound type.
        let effective_constraints = if TypeVarType::is_self(dest_type) {
            constraints
        } else {
            None
        };

        // Arguments in TypeScript order: the concrete type, then the child addendum.
        let concrete_updated_type =
            evaluator.make_top_level_type_vars_concrete(updated_type, false, None);
        let child_diag = diag.map(|diag| diag.create_addendum());
        if !evaluator.assign_type(
            bound_type,
            concrete_updated_type,
            child_diag,
            effective_constraints,
            AssignTypeFlags::Default,
            recursion_count,
        ) {
            // Avoid adding a message that will confuse users if the TypeVar was
            // synthesized for internal purposes.
            if !dest_type.d().shared.get().is_synthesized.get() {
                if let Some(diag) = diag {
                    let source_type = evaluator.print_type(updated_type, None);
                    let dest_type_text = evaluator.print_type(bound_type, None);
                    let name = TypeVarType::get_readable_name(dest_type, true);
                    diag.add_message(LocAddendum::type_bound().format(&[
                        ("sourceType", &source_type),
                        ("destType", &dest_type_text),
                        ("name", &name),
                    ]));
                }
            }
            return false;
        }
    }

    if let Some(constraints) = constraints {
        constraints.set_bounds(
            dest_type,
            new_lower_bound,
            new_upper_bound,
            Some(flags.any(
                AssignTypeFlags::PopulateExpectedType | AssignTypeFlags::RetainLiteralsForTypeVar,
            )),
        );
    }

    true
}

// analyzer/constraintSolver.ts:1014
pub(crate) fn assign_constrained_type_var(
    evaluator: &TypeEvaluator,
    dest_type: TypeVarType,
    src_type: P<Type>,
    diag: Option<P<DiagnosticAddendum>>,
    constraints: Option<P<ConstraintTracker>>,
    flags: AssignTypeFlags,
    recursion_count: u32,
) -> bool {
    let mut constrained_type: Option<P<Type>>;
    let concrete_src_type = evaluator.make_top_level_type_vars_concrete(src_type, false, None);
    let cur_entry = constraints.and_then(|constraints| {
        constraints
            .get_main_constraint_set()
            .get_type_var(dest_type)
    });

    let cur_upper_bound = cur_entry.as_ref().and_then(|entry| entry.upper_bound);
    let cur_lower_bound = cur_entry.as_ref().and_then(|entry| entry.lower_bound);
    let mut retain_literals = false;

    let dest_constraints = dest_type.d().shared.get().constraints.borrow().clone();

    if is_type_var(src_type) {
        constrained_type = None;
        if evaluator.assign_type(
            dest_type.0,
            concrete_src_type,
            /* diag */ None,
            /* constraints */ None,
            AssignTypeFlags::Default,
            recursion_count,
        ) {
            constrained_type = Some(src_type);

            // If the source and dest are both instantiables (type[T]), then
            // we need to convert to an instance (T).
            if TypeBase::is_instantiable(src_type) {
                constrained_type = Some(convert_to_instance(
                    src_type, /* includeSubclasses */ false,
                ));
            }
        }
    } else {
        let mut is_compatible = true;

        // Subtypes that are not conditionally dependent on the dest type var
        // must all map to the same constraint. For example, Union[str, bytes]
        // cannot be assigned to AnyStr.
        let mut unconditional_constraint_index: Option<usize> = None;

        // Find the narrowest constrained type that is compatible.
        let mapped = map_subtypes(
            concrete_src_type,
            &mut |src_subtype| {
                let mut constrained_subtype: Option<P<Type>> = None;

                if is_any_or_unknown(src_subtype) {
                    return Some(src_subtype);
                }

                let mut constraint_index_used: Option<usize> = None;
                for (i, &constraint) in dest_constraints.iter().enumerate() {
                    let adjusted_constraint = if TypeBase::is_instantiable(dest_type.0) {
                        convert_to_instantiable(constraint, true)
                    } else {
                        constraint
                    };
                    if evaluator.assign_type(
                        adjusted_constraint,
                        src_subtype,
                        /* diag */ None,
                        /* constraints */ None,
                        AssignTypeFlags::Default,
                        recursion_count,
                    ) {
                        let narrower = match constrained_subtype {
                            None => true,
                            Some(constrained_subtype) => evaluator.assign_type(
                                if TypeBase::is_instantiable(dest_type.0) {
                                    convert_to_instantiable(constrained_subtype, true)
                                } else {
                                    constrained_subtype
                                },
                                adjusted_constraint,
                                /* diag */ None,
                                /* constraints */ None,
                                AssignTypeFlags::Default,
                                recursion_count,
                            ),
                        };
                        if narrower {
                            constrained_subtype = Some(add_condition_to_type(
                                constraint,
                                get_type_condition(src_subtype).as_deref(),
                                None,
                            ));
                            constraint_index_used = Some(i);
                        }
                    }
                }

                if constrained_subtype.is_none() {
                    // We found a source subtype that is not compatible with the dest.
                    // This is OK if we're handling the contravariant case because only
                    // one subtype needs to be assignable in that case.
                    if !flags.any(AssignTypeFlags::Contravariant) {
                        is_compatible = false;
                    }
                }

                // If this subtype isn't conditional, make sure it maps to the same
                // constraint index as previous unconditional subtypes.
                if let Some(constraint_index_used) = constraint_index_used {
                    if get_type_condition(src_subtype).is_none() {
                        if unconditional_constraint_index
                            .is_some_and(|index| index != constraint_index_used)
                        {
                            is_compatible = false;
                        }

                        unconditional_constraint_index = Some(constraint_index_used);
                    }
                }

                constrained_subtype
            },
            None,
        );
        constrained_type = Some(mapped);

        if is_never(mapped) || !is_compatible {
            constrained_type = None;
        }

        // If the type is a union, see if the entire union is assignable to one
        // of the constraints.
        if constrained_type.is_none() && is_union(concrete_src_type) {
            constrained_type = dest_constraints.iter().copied().find(|&constraint| {
                let adjusted_constraint = if TypeBase::is_instantiable(dest_type.0) {
                    convert_to_instantiable(constraint, true)
                } else {
                    constraint
                };
                evaluator.assign_type(
                    adjusted_constraint,
                    concrete_src_type,
                    /* diag */ None,
                    /* constraints */ None,
                    AssignTypeFlags::Default,
                    recursion_count,
                )
            });
        }
    }

    // If there was no constrained type that was assignable
    // or there were multiple types that were assignable and they
    // are not conditional, it's an error.
    let Some(constrained_type) = constrained_type else {
        if let Some(diag) = diag {
            let type_text = evaluator.print_type(src_type, None);
            let name = dest_type.d().shared.get().name.borrow().clone();
            diag.add_message(
                LocAddendum::type_constrained_type_var()
                    .format(&[("type", &type_text), ("name", &name)]),
            );
        }
        return false;
    };
    if is_literal_type_or_union(constrained_type, false) {
        retain_literals = true;
    }

    match cur_lower_bound {
        Some(cur_lower_bound) if !is_any_or_unknown(cur_lower_bound) => {
            if !evaluator.assign_type(
                cur_lower_bound,
                constrained_type,
                /* diag */ None,
                /* constraints */ None,
                AssignTypeFlags::Default,
                recursion_count,
            ) {
                // Handle the case where one of the constrained types is a wider
                // version of another constrained type that was previously assigned
                // to the type variable.
                if evaluator.assign_type(
                    constrained_type,
                    cur_lower_bound,
                    /* diag */ None,
                    /* constraints */ None,
                    AssignTypeFlags::Default,
                    recursion_count,
                ) {
                    if let Some(constraints) = constraints {
                        constraints.set_bounds(
                            dest_type,
                            Some(constrained_type),
                            cur_upper_bound,
                            None,
                        );
                    }
                } else {
                    if let Some(diag) = diag {
                        let type_text = evaluator.print_type(constrained_type, None);
                        let name = evaluator.print_type(cur_lower_bound, None);
                        diag.add_message(
                            LocAddendum::type_constrained_type_var()
                                .format(&[("type", &type_text), ("name", &name)]),
                        );
                    }
                    return false;
                }
            }
        }
        _ => {
            // Assign the type to the type var.
            if let Some(constraints) = constraints {
                constraints.set_bounds(
                    dest_type,
                    Some(constrained_type),
                    cur_upper_bound,
                    Some(retain_literals),
                );
            }
        }
    }

    true
}

// analyzer/constraintSolver.ts:1207
/// TS defaults: recursionCount = 0.
pub(crate) fn assign_param_spec(
    evaluator: &TypeEvaluator,
    dest_type: ParamSpecType,
    src_type: P<Type>,
    diag: Option<P<DiagnosticAddendum>>,
    constraints: Option<P<ConstraintTracker>>,
    recursion_count: u32,
) -> bool {
    // If there is no constraint tracker, there's nothing to do because
    // param specs have no upper bounds or constraints.
    let Some(constraints) = constraints else {
        return true;
    };

    let dest_type_var = TypeVarType(dest_type.0);
    let mut is_assignable = true;
    let mut adj_src_type = if is_param_spec(src_type) {
        src_type
    } else {
        convert_type_to_param_spec_value(src_type).0
    };
    if is_function(adj_src_type) {
        adj_src_type = simplify_function_to_param_spec(FunctionType(adj_src_type));
    }

    constraints.do_for_each_constraint_set(&mut |constraint_set, _| {
        if is_param_spec(adj_src_type) {
            let existing_type = constraint_set
                .get_type_var(dest_type_var)
                .and_then(|entry| entry.lower_bound);
            if let Some(existing_type) = existing_type {
                let param_spec_value = convert_type_to_param_spec_value(existing_type);
                let existing_type_param_spec =
                    FunctionType::get_param_spec_from_args_kwargs(param_spec_value);
                let existing_type_without_args_kwargs =
                    FunctionType::clone_remove_param_spec_args_kwargs(param_spec_value, false);

                let has_no_params = existing_type_without_args_kwargs
                    .d()
                    .shared
                    .get()
                    .parameters
                    .get()
                    .borrow()
                    .is_empty();
                if has_no_params {
                    if let Some(existing_type_param_spec) = existing_type_param_spec {
                        // If there's an existing entry that matches, that's fine.
                        if is_type_same(
                            existing_type_param_spec.0,
                            adj_src_type,
                            &TypeSameOptions::default(),
                            recursion_count,
                        ) {
                            return;
                        }
                    }
                }
            } else {
                constraint_set.set_bounds(dest_type_var, Some(adj_src_type), None, None);
                return;
            }
        } else if is_function(adj_src_type) {
            let new_function = adj_src_type;
            let mut update_context_with_new_function = false;

            let existing_type = constraint_set
                .get_type_var(dest_type_var)
                .and_then(|entry| entry.lower_bound);
            if let Some(existing_type) = existing_type {
                // Convert the remaining portion of the signature to a function
                // for comparison purposes.
                let existing_function = simplify_function_to_param_spec(
                    convert_type_to_param_spec_value(existing_type),
                );

                let is_new_narrower = evaluator.assign_type(
                    existing_function,
                    new_function,
                    /* diag */ None,
                    /* constraints */ None,
                    AssignTypeFlags::SkipReturnTypeCheck,
                    recursion_count,
                );

                let is_new_wider = evaluator.assign_type(
                    new_function,
                    existing_function,
                    /* diag */ None,
                    /* constraints */ None,
                    AssignTypeFlags::SkipReturnTypeCheck,
                    recursion_count,
                );

                // Should we widen the type?
                if is_new_narrower && is_new_wider {
                    // The new type is both a supertype and a subtype of the existing type.
                    // That means the two types are the same or one (or both) have the type
                    // "..." (which is the ParamSpec equivalent of "Any"). If only one has
                    // the type "...", we'll prefer the other one. This is analogous to
                    // what we do with regular TypeVars, where we prefer non-Any values.
                    if !FunctionType::is_gradual_callable_form(FunctionType(new_function)) {
                        update_context_with_new_function = true;
                    } else {
                        return;
                    }
                } else if is_new_wider {
                    update_context_with_new_function = true;
                } else if is_new_narrower {
                    // The existing function is already narrower than the new function, so
                    // no need to narrow it further.
                    return;
                }
            } else {
                update_context_with_new_function = true;
            }

            if update_context_with_new_function {
                constraint_set.set_bounds(dest_type_var, Some(new_function), None, None);
                return;
            }
        } else if is_any_or_unknown(adj_src_type) {
            return;
        }

        if let Some(diag) = diag {
            let type_text = evaluator.print_type(adj_src_type, None);
            let name = dest_type.d().shared.get().name.borrow().clone();
            diag.add_message(
                LocAddendum::type_param_spec().format(&[("type", &type_text), ("name", &name)]),
            );
        }

        is_assignable = false;
    });

    is_assignable
}

// analyzer/constraintSolver.ts:1323
pub(crate) fn type_var_occurs_in(type_var: TypeVarType, type_: P<Type>) -> bool {
    let same_name_and_scope = |other: TypeVarType| -> bool {
        *other.d().shared.get().name.borrow() == *type_var.d().shared.get().name.borrow()
            && other.d().priv_.borrow().scope_id == type_var.d().priv_.borrow().scope_id
    };

    // A bare top-level TypeVar reference is not a cycle. Compare by name +
    // scope id rather than identity since pyright sometimes clones TypeVars.
    if is_type_var(type_) && same_name_and_scope(TypeVarType(type_)) {
        return false;
    }

    // Top-level union members that are exactly `typeVar` are also fine; only
    // count occurrences strictly inside other types.
    if is_union(type_) {
        let subtypes = UnionType(type_).d().priv_.borrow().subtypes.clone();
        for &subtype in subtypes.iter() {
            if type_var_occurs_in(type_var, subtype) {
                return true;
            }
        }
        return false;
    }

    let tvars = get_type_var_args_recursive(type_, 0);
    for tv in tvars {
        if same_name_and_scope(tv) {
            return true;
        }
    }
    false
}

// analyzer/constraintSolver.ts:1353
pub(crate) fn widen_type_for_type_var_tuple(
    evaluator: &TypeEvaluator,
    type1: P<Type>,
    type2: P<Type>,
    is_invariant: bool,
    recursion_count: u32,
) -> Option<P<Type>> {
    // If the two types are not unpacked tuples, we can't combine them.
    if !is_unpacked_class(type1) || !is_unpacked_class(type2) {
        return None;
    }

    // If the two unpacked tuples are not the same length, we can't combine them.
    let args1 = ClassType(type1)
        .d()
        .priv_
        .borrow()
        .tuple_type_args
        .map(|tuple_type_args| tuple_type_args.get().borrow())
        .as_deref()
        .map(Vec::len);
    let args2 = ClassType(type2)
        .d()
        .priv_
        .borrow()
        .tuple_type_args
        .map(|tuple_type_args| tuple_type_args.get().borrow())
        .as_deref()
        .map(Vec::len);
    match (args1, args2) {
        (Some(len1), Some(len2)) if len1 == len2 => {}
        _ => return None,
    }

    let stripped_type1 = strip_literal_value_for_unpacked_tuple(evaluator, type1);
    let stripped_type2 = strip_literal_value_for_unpacked_tuple(evaluator, type2);

    if !is_unpacked_class(stripped_type1) || !is_unpacked_class(stripped_type2) {
        return None;
    }

    let tuple_type_args1 = ClassType(stripped_type1)
        .d()
        .priv_
        .borrow()
        .tuple_type_args
        .map(|tuple_type_args| tuple_type_args.borrow().clone());
    let tuple_type_args2 = ClassType(stripped_type2)
        .d()
        .priv_
        .borrow()
        .tuple_type_args
        .map(|tuple_type_args| tuple_type_args.borrow().clone());
    let (Some(tuple_type_args1), Some(tuple_type_args2)) = (tuple_type_args1, tuple_type_args2)
    else {
        return None;
    };

    for i in 0..tuple_type_args1.len() {
        let type_arg1 = &tuple_type_args1[i];
        // JS reads `undefined` past the end of the second array.
        let type_arg2 = tuple_type_args2.get(i)?;

        if type_arg1.is_unbounded != type_arg2.is_unbounded
            || type_arg1.is_optional.unwrap_or(false) != type_arg2.is_optional.unwrap_or(false)
        {
            return None;
        }
    }

    if is_type_same(
        stripped_type1,
        stripped_type2,
        &TypeSameOptions::default(),
        0,
    ) {
        return Some(stripped_type1);
    }

    // The typing spec indicates that a TypeVarTuple bound in multiple locations
    // should resolve to "exactly the same type". In an invariant context we honor
    // that strictly and bail out when the tuples differ. In non-invariant contexts,
    // however, requiring an exact match is overly restrictive and rejects valid
    // heterogeneous bindings, so we instead widen element-wise (mirroring how normal
    // TypeVars widen incompatible lower bounds into a union).
    if is_invariant {
        return None;
    }

    let tuple_type_args: Vec<TupleTypeArg> = tuple_type_args1
        .iter()
        .enumerate()
        .map(|(index, type_arg1)| {
            let type_arg2 = &tuple_type_args2[index];

            let widened_type = if evaluator.assign_type(
                type_arg1.type_,
                type_arg2.type_,
                None,
                None,
                AssignTypeFlags::Default,
                recursion_count,
            ) {
                type_arg1.type_
            } else if evaluator.assign_type(
                type_arg2.type_,
                type_arg1.type_,
                None,
                None,
                AssignTypeFlags::Default,
                recursion_count,
            ) {
                type_arg2.type_
            } else {
                combine_types(
                    &[type_arg1.type_, type_arg2.type_],
                    Some(&CombineTypesOptions {
                        max_subtype_count: Some(MAX_SUBTYPE_COUNT_FOR_TYPE_VAR_LOWER_BOUND),
                        ..Default::default()
                    }),
                )
            };

            TupleTypeArg {
                type_: widened_type,
                is_unbounded: type_arg1.is_unbounded,
                is_optional: type_arg1.is_optional,
            }
        })
        .collect();

    Some(
        specialize_tuple_class(
            ClassType(stripped_type1),
            &tuple_type_args,
            /* isTypeArgExplicit */ true,
            /* isUnpacked */ true,
        )
        .0,
    )
}

// analyzer/constraintSolver.ts:1438
pub(crate) fn strip_literal_value_for_unpacked_tuple(
    evaluator: &TypeEvaluator,
    type_: P<Type>,
) -> P<Type> {
    if !is_unpacked_class(type_) {
        return type_;
    }
    let Some(type_args) = ClassType(type_).d().priv_.borrow().tuple_type_args.map(|tuple_type_args| tuple_type_args.borrow().clone()) else {
        return type_;
    };

    let mut stripped_literal = false;
    let tuple_type_args: Vec<TupleTypeArg> = type_args
        .iter()
        .map(|arg| {
            let stripped_type = strip_type_form(evaluator.strip_literal_value(arg.type_));

            if stripped_type != arg.type_ {
                stripped_literal = true;
            }

            TupleTypeArg {
                is_unbounded: arg.is_unbounded,
                is_optional: arg.is_optional,
                type_: stripped_type,
            }
        })
        .collect();

    if !stripped_literal {
        return type_;
    }

    specialize_tuple_class(
        ClassType(type_),
        &tuple_type_args,
        /* isTypeArgExplicit */ true,
        /* isUnpacked */ true,
    )
    .0
}

// analyzer/constraintSolver.ts:1467
pub(crate) fn log_constraints(
    evaluator: &TypeEvaluator,
    constraints: P<ConstraintTracker>,
    indent: &str,
) {
    let constraint_sets = constraints.get_constraint_sets();
    let constraint_set_count = constraint_sets.len();
    if constraint_set_count == 0 {
        println!("{indent}  no signatures");
    } else if constraint_set_count == 1 {
        log_type_var_constraint_set(evaluator, constraint_sets[0], &format!("{indent}  "));
    } else {
        constraints.do_for_each_constraint_set(&mut |set, index| {
            println!("{indent}  signature {index}");
            log_type_var_constraint_set(evaluator, set, &format!("{indent}    "));
        });
    }
}

// analyzer/constraintSolver.ts:1481
pub(crate) fn log_type_var_constraint_set(
    evaluator: &TypeEvaluator,
    context: P<ConstraintSet>,
    indent: &str,
) {
    let mut logged_constraint = false;

    for entry in context.get_type_vars() {
        let type_var_name = format!(
            "{}{}",
            indent,
            entry.type_var.d().shared.get().name.borrow()
        );
        let lower_bound = entry.lower_bound;
        let upper_bound = entry.upper_bound;

        // Log the lower and upper bounds.
        match (lower_bound, upper_bound) {
            (Some(lower_bound), Some(upper_bound))
                if is_type_same(lower_bound, upper_bound, &TypeSameOptions::default(), 0) =>
            {
                println!(
                    "{} = {}",
                    type_var_name,
                    evaluator.print_type(lower_bound, None)
                );
                logged_constraint = true;
            }
            _ => {
                if let Some(lower_bound) = lower_bound {
                    println!(
                        "{} ≤ {}",
                        type_var_name,
                        evaluator.print_type(lower_bound, None)
                    );
                    logged_constraint = true;
                }
                if let Some(upper_bound) = upper_bound {
                    println!(
                        "{} ≥ {}",
                        type_var_name,
                        evaluator.print_type(upper_bound, None)
                    );
                    logged_constraint = true;
                }
            }
        }
    }

    if !logged_constraint {
        println!("{indent}no constraints");
    }
}
